// Corpus generator for the "segwit-rejects" family: strings that decode fine at
// the bech32 layer but must be rejected by bech32.decode()'s segwit rules.
//
// Rejection routes exercised here:
//   R1  data[0] > 16                      (witness version 17..31)
//   R2  program length 0                  (payload converts to [])
//   R3  program length 1                  (len < 2)
//   R4  program length 41..               (len > 40)
//   R5  witver 0 with length not in {20,32}
//   R6  convertbits(...,5,8,false) -> null via `bits >= frombits`
//       (payload length mod 8 in {1,3,6})
//   R7  convertbits -> null via non-zero trailing partial group
//   R8  data == []  (no witness version symbol at all -- would IndexError in
//       Python if the length guard did not fire first)
//
// Plus accept-side controls straddling every one of those boundaries.

import { writeFileSync, mkdirSync } from 'node:fs';
import { bech32Encode, convertbits } from '/tmp/probe/gen.mjs';

const corpus = [];
const seen = new Set();
const add = (argv) => {
